/* ==========================================================================
   Mi RCR — logos.js
   Logos institucionales como PNG transparente en data URI.
   Van embebidos a propósito: el PDF se genera con html2canvas y así no
   depende de la red ni del orden de carga de las imágenes.
   Generados desde los SVG originales a 220 px de alto.
   El campo "ar" es la relación ancho/alto: sirve para escalar sin deformar.
   ========================================================================== */

window.LOGOS = {
  /* Vidrio Mejor Planeta — 450x220 */
  vidrio: { nombre: "Vidrio Mejor Planeta", ar: 2.0455,
    src: "data:image/png;base64," },
  /* ReCircula — 674x220 */
  recircula: { nombre: "ReCircula", ar: 3.0659,
    src: "data:image/png;base64," },
  /* Juntos Por La Vida — 516x220 */
  juntos: { nombre: "Juntos Por La Vida", ar: 2.3447,
    src: "data:image/png;base64," },
  /* Redes Con Rostro — 265x220 */
  rcr: { nombre: "Redes Con Rostro", ar: 1.2025,
    src: "data:image/png;base64," },
  /* Tesalia CBC — 903x220 */
  tesalia: { nombre: "Tesalia CBC", ar: 4.1065,
    src: "data:image/png;base64," },
  /* Provefrut — 1299x220 */
  provefrut: { nombre: "Provefrut", ar: 5.9064,
    src: "data:image/png;base64," },
  /* Nintanga — 1000x220 */
  nintanga: { nombre: "Nintanga", ar: 4.5459,
    src: "data:image/png;base64," },
  /* Procongelados — 1100x220 */
  procongelados: { nombre: "Procongelados", ar: 4.999,
    src: "data:image/png;base64," }
};

/* Devuelve un <img> escalado por alto, conservando la proporción. */
window.logoImg = function (key, alto) {
  var L = window.LOGOS[key];
  if (!L) return '';
  return '<img src="' + L.src + '" alt="' + L.nombre + '"' +
         ' style="height:' + alto + 'px;width:' + Math.round(alto * L.ar) + 'px;display:block">';
};
